import {renderCourseGrid,renderSettingsPage,refreshCourseProgress,liveMarkup} from './planner-ui.js';
import {createUpdateUI} from './update-ui.js';
import {createManagementUI} from './manage-ui.js';
import {createExamUI} from './exams-ui.js';
import {createShareUI} from './share-ui.js';
import {installTimetableMotion} from './motion.js';
import {DEFAULT_SETTINGS,getWeek,getWeekDates,parseWeeks} from './core.js';
import {uid,localDate,addDays,makeSemester,createState,migrateState,validateState,getProfile,occurrencesOn,occurrenceStatus,notificationEvents} from './engine.js';
import {loadState,commitState,recoveries,STATE_KEY} from './state-store.js';
import {parseSchedule} from './importer.js';
import {esc,clone,icon,DAYS,button,select,field,input,weeksText,toast,sheet,closeSheet,backSheet,errorBox,submit} from './ui.js';

let state,storageError='',sharing,management,exams,motion,updater,importTargetId='',returnToImport=false;
try{state=loadState();}catch(e){storageError=e.message;state=createState();}
const app=document.querySelector('#app');
const tabHistory=[];
let tab='table',week=1,threeStart=localDate(),occurrenceMap=new Map(),courseDraft=null,draftEditing=false,importPreview=null,restoreDraft=null,pdfBusy=false;
const semester=()=>state.semesters.find(s=>s.id===state.activeSemesterId)||state.semesters[0];
const currentWeek=()=>getWeek(localDate(),semester().startDate);
const importSemester=()=>state.semesters.find(s=>s.id===importTargetId)||semester();
const clampWeek=w=>Math.max(1,Math.min(semester().totalWeeks,w));
week=clampWeek(currentWeek());
let notificationStatus={granted:false,exact:false,enabled:false,ongoing:false};
const mmdd=date=>`${Number(date.slice(5,7))}/${Number(date.slice(8))}`;
const dayNumber=date=>new Date(`${date}T12:00:00`).getDay()||7;
const shortLocation=location=>location.replace(/^.*?校区\s*/,'').trim()||location||'地点待定';
const displayName=c=>c.shortName||c.name.replace(/[★☆]+$/u,'').trim();
const periodOptions=(s=semester())=>Array.from({length:Math.min(...s.profiles.map(p=>p.periods.length))},(_,i)=>[i+1,`第 ${i+1} 节`]);
const sessionText=s=>`周${DAYS[s.day-1]} · ${s.startPeriod}–${s.endPeriod} 节`;
const header=(title,desc='')=>`<div class="section-heading"><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
function holiday(date){return semester().holidayLabels.find(h=>h.date===date)?.name||holiday2026(date);}
function holiday2026(date){const ranges=[['01-01','01-03','元旦'],['02-15','02-23','春节'],['04-04','04-06','清明'],['05-01','05-05','劳动节'],['06-19','06-21','端午'],['09-25','09-27','中秋'],['10-01','10-07','国庆']];if(!date.startsWith('2026-'))return '';const d=date.slice(5);return ranges.find(([a,b])=>d>=a&&d<=b)?.[2]||'';}
function syncNative(){
  if(!window.Android?.syncSchedule||storageError)return;
  const n=state.preferences.notifications;
  try{const events=(n.enabled||n.ongoing)?notificationEvents(semester()).map(o=>({id:o.id,type:o.kind||'course',name:o.name,location:o.location,start:o.startMs,end:o.endMs,segments:o.breakMode==='continuous'?[{start:o.startMs,end:o.endMs}]:o.segments.map(s=>({start:s.startMs,end:s.endMs}))})):[];Android.syncSchedule(JSON.stringify({...n,events}));if(Android.getNotificationStatus)notificationStatus=JSON.parse(Android.getNotificationStatus());}catch(e){toast(`通知计划未同步：${e.message}`);}
}
function save(next,label=''){if(storageError){toast('请先导出原始备份并恢复有效数据，避免覆盖旧课表');return false;}try{state=commitState(next,label);syncNative();sharing?.onStateSaved?.();return true;}catch(e){toast(`未能保存：${e.message}`);return false;}}
function updateSemester(next,label=''){return save({...state,semesters:state.semesters.map(s=>s.id===next.id?next:s)},label);}
function render(){try{occurrenceMap=new Map();app.innerHTML=`${storageError?`<div class="storage-error">原数据无法读取：${esc(storageError)}。请先导出备份。</div>`:''}<main class="page ${tab==='table'?'planner-page':''}">${tab==='table'?renderTable():tab==='today'?renderToday():renderSettings()}</main><nav class="bottom-nav" aria-label="主导航">${[['table','grid','课表'],['today','sun','今天'],['settings','settings','设置']].map(([key,i,label])=>`<button class="nav-item ${tab===key?'active':''}" data-action="tab" data-tab="${key}" ${tab===key?'aria-current="page"':''}><span class="nav-icon">${icon(i,21)}</span>${label}</button>`).join('')}</nav>`;refreshCourseProgress(app,occurrenceMap);}catch(e){app.innerHTML=`<div class="storage-error">页面显示失败：${esc(e.message)}。数据未被覆盖。</div>`;console.error(e);}}
function visibleDates(){return state.preferences.viewMode==='three'?Array.from({length:3},(_,i)=>addDays(threeStart,i)):getWeekDates(semester().startDate,week).slice(0,semester().showWeekend?7:5);}
function renderTable(){
  const s=semester(),dates=visibleDates(),three=state.preferences.viewMode==='three',groups=dates.map(d=>occurrencesOn(s,d));groups.flat().forEach(o=>occurrenceMap.set(o.id,o));
  const actual=currentWeek(),status=localDate()<s.startDate?'尚未开学':actual>s.totalWeeks?'学期已结束':`今天第 ${actual} 周`,maxPeriods=Math.max(...dates.map(d=>getProfile(s,d).periods.length)),profiles=[...new Set(dates.map(d=>getProfile(s,d).name))];
  return `<header class="planner-head"><button data-action="semesters" class="semester-switch"><span>${esc(s.name)}</span>${icon('down',13)}</button><span class="head-status">${status}</span>${button('add-menu',icon('plus',20),'round-add','aria-label="添加课程"')}</header><div class="planner-tools"><button class="week-picker" data-action="choose-week">${three?`${mmdd(dates[0])}–${mmdd(dates.at(-1))}`:`第 ${String(week).padStart(2,'0')} 周`}${icon('down',14)}</button><div class="view-toggle"><button data-action="view" data-view="week" class="${!three?'active':''}">一周</button><button data-action="view" data-view="three" class="${three?'active':''}">三天</button></div><div class="week-arrows">${button('prev',icon('left',15),'arrow-button','aria-label="上一段日期"')}${button('today-date','今天','this-week')}${button('next',icon('right',15),'arrow-button','aria-label="下一段日期"')}</div></div><section class="table-shell ${three?'three-day':''}" aria-label="课程表"><div class="day-header" style="--days:${dates.length}"><div class="month-tag">${Number(dates[0].slice(5,7))}月</div>${dates.map(d=>{const rule=s.dayRules.find(r=>r.date===d);return `<button class="day-label ${d===localDate()?'current':''}" data-action="day-detail" data-date="${d}"><span>周${DAYS[dayNumber(d)-1]}</span><span class="date-number">${Number(d.slice(8))}</span><small class="day-tag ${rule?'adjusted':''}">${esc(rule?(rule.type==='off'?'停课':'补课'):holiday(d))}</small></button>`;}).join('')}</div>${renderExamStrip(dates,groups)}${s.courses.length?renderGrid(dates,groups.map(items=>items.filter(o=>o.kind!=='exam')),maxPeriods):`<div class="empty-grid"><div class="empty-note"><span class="sprout">${icon('leaf',28)}</span><h3>从一张课表开始</h3><p>导入教务网页或 PDF<br>也可以手动安排第一门课</p>${button('import','导入课表','primary','style="margin-top:18px"')}</div></div>`}</section><div class="legend"><span>${groups.flat().length} 次安排 · ${esc(profiles.join(' / '))}</span>${button('calendar',`${icon('calendar',13)} 调休 / 调课`,'text-button')}</div>${dates.some(d=>getProfile(s,d).id!==getProfile(s,dates[0]).id)?'<p class="calendar-footnote">本周跨越作息切换日；左侧显示标注日期的时间，其他作息的课程卡片附实际时间。</p>':''}${dates.some(d=>holiday(d))?'<p class="calendar-footnote">节假日为日期标记，学校停课与补课请在日历中设置。</p>':''}${!s.courses.length?`<div class="empty-actions">${button('add','手动添加课程')}${button('semester-edit','设置开学日期')}</div>`:''}`;
}
function renderExamStrip(dates,groups){if(!groups.some(items=>items.some(o=>o.kind==='exam')))return '';return `<div class="exam-strip" style="--days:${dates.length}"><span class="exam-strip-label">考试</span>${groups.map(items=>`<div class="exam-day">${items.filter(o=>o.kind==='exam').map(o=>`<button data-action="exam-detail" data-id="${esc(o.examId)}" class="exam-chip"><strong>${esc(o.name)}</strong><span>${o.segments[0].start}<br>${o.segments[0].end}</span>${o.conflict?'<b>冲突</b>':''}</button>`).join('')}</div>`).join('')}</div>`;}
function renderGrid(dates,groups,maxPeriods){return renderCourseGrid({semester:semester(),dates,groups,maxPeriods});}
function renderToday(){const date=localDate(),items=occurrencesOn(semester(),date);items.forEach(o=>occurrenceMap.set(o.id,o));return `${header('今天',`${date} · 星期${DAYS[dayNumber(date)-1]}${holiday(date)?` · ${esc(holiday(date))}`:''}`)}<div class="today-summary"><strong>${items.length}</strong><span>次课程安排</span><span class="pill">${esc(getProfile(semester(),date).name)}</span></div>${items.length?items.map(o=>{const st=occurrenceStatus(o,new Date());return `<article class="agenda-item"><div class="agenda-time">${o.segments[0]?.start||''}<small>${o.segments.at(-1)?.end||''}</small></div><button class="agenda-card c${o.color}" data-live-id="${esc(o.id)}" data-action="detail" data-id="${esc(o.id)}" style="text-align:left"><h3>${esc(o.name)}</h3><p>${icon('pin',14)}${esc(o.location||'地点待定')}</p><span class="small-label">${esc(st.label)}${o.changeLabel?` · ${esc(o.changeLabel)}`:''}</span>${['class','break'].includes(st.phase)?`<div class="live-time">${st.phase==='break'?'课间':o.kind==='exam'?'考试':'本小节'} · ${Math.max(0,Math.ceil(st.remainingMs/60000))} 分钟后${st.phase==='break'?'继续上课':st.nextBoundaryMs===o.endMs?(o.kind==='exam'?'考试结束':'下课'):'休息'}</div>`:''}${liveMarkup(o.id)}</button></article>`;}).join(''):`<div class="empty-today">${icon('sun',44)}<h2>今天没有课程</h2><p>有临时补课或调整，可以在日历中添加。</p>${button('calendar','查看日历')}</div>`}<div class="helper-box">${icon('bell',16)} ${state.preferences.notifications.enabled?'课前提醒已开启':'课前提醒尚未开启'}${button('notifications','设置提醒','text-button')}</div>`;}
function settingRow(action,i,title,description,trailing=''){return `<button class="setting-row" data-action="${action}"><span class="setting-icon">${icon(i)}</span><span class="row-text"><strong>${title}</strong><small>${description}</small></span>${trailing||icon('right',15)}</button>`;}
function renderSettings(){return renderSettingsPage(state);}

function chooseWeek(){sheet('选择周次',`<p class="sheet-subtitle">${esc(semester().name)}</p><div class="week-grid">${Array.from({length:semester().totalWeeks},(_,i)=>button('set-week',`${String(i+1).padStart(2,'0')}<small>${i+1===currentWeek()?'本周':'WEEK'}</small>`,`week-option ${week===i+1?'active':''}`,`data-week="${i+1}"`)).join('')}</div>`);}
function newSession(){return {id:uid(),day:1,startPeriod:1,endPeriod:Math.min(2,periodOptions().length),weeks:Array.from({length:semester().totalWeeks},(_,i)=>i+1),teacher:'',location:'',breakMode:'normal'};}
function editCourse(id){const c=semester().courses.find(c=>c.id===id);courseDraft=c?clone(c):{id:uid(),name:'',shortName:'',color:0,assessment:'未设置',nature:'',note:'',sessions:[newSession()]};draftEditing=!!c;showCourseEditor();}
function sessionEditor(s,i){return `<fieldset class="session-editor" data-session-id="${esc(s.id)}"><div class="session-heading"><strong>安排 ${i+1}</strong>${courseDraft.sessions.length>1?button('remove-session','移除','text-button',`data-index="${i}"`):''}</div><div class="form-row three">${field('星期',select(`day-${i}`,DAYS.map((d,j)=>[j+1,`周${d}`]),s.day))}${field('开始',select(`startPeriod-${i}`,periodOptions(),s.startPeriod))}${field('结束',select(`endPeriod-${i}`,periodOptions(),s.endPeriod))}</div><div class="form-row">${field('教室',input(`location-${i}`,s.location,'text','maxlength="150" placeholder="地点可各不相同"'))}${field('教师',input(`teacher-${i}`,s.teacher,'text','maxlength="100" placeholder="选填"'))}</div>${field('上课周次',input(`weeks-${i}`,s.weeks.join(','),'text','required placeholder="例如 1-16周(单)"'))}<div class="week-shortcuts">${[['all','全学期'],['odd','单周'],['even','双周']].map(([v,t])=>button('session-weeks',t,'',`data-index="${i}" data-value="${v}"`)).join('')}</div>${field('小节之间',select(`breakMode-${i}`,[['normal','按作息表休息'],['continuous','连上，不设课间']],s.breakMode))}</fieldset>`;}
function showCourseEditor(){const c=courseDraft;sheet(draftEditing?'编辑课程':'添加课程',`<form id="course-form">${field('课程名称',input('name',c.name,'text','required maxlength="100" placeholder="例如 高等数学"'))}<div class="form-row">${field('课表简称',input('shortName',c.shortName,'text','maxlength="30" placeholder="选填，详情保留全名"'))}${field('考核方式',`<input name="assessment" list="assessment-options" value="${esc(c.assessment)}" maxlength="30"><datalist id="assessment-options"><option value="未设置"><option value="考试"><option value="考查"></datalist>`)}</div>${field('课程性质',input('nature',c.nature,'text','maxlength="30" placeholder="必修、选修、实验……（选填）"'))}<span class="field-label">课程颜色</span><div class="color-options">${Array.from({length:8},(_,i)=>button('color','',`color-dot c${i} ${c.color===i?'selected':''}`,`data-color="${i}" aria-label="颜色 ${i+1}"`)).join('')}</div><div id="sessions">${c.sessions.map(sessionEditor).join('')}</div>${button('add-session',`${icon('plus',16)} 添加另一个上课时间`,'secondary full-width')}${field('备注',input('note',c.note,'text','maxlength="2000"'))}${submit(draftEditing?'保存整门课程':'保存课程')}</form>`);}
function readCourseDraft(){const f=document.querySelector('#course-form');if(!f)return;const values=Object.fromEntries(new FormData(f));for(const k of ['name','shortName','assessment','nature','note'])courseDraft[k]=values[k].trim();const selected=f.querySelector('.color-dot.selected');if(selected)courseDraft.color=Number(selected.dataset.color);courseDraft.sessions=courseDraft.sessions.map((s,i)=>({...s,day:Number(values[`day-${i}`]),startPeriod:Number(values[`startPeriod-${i}`]),endPeriod:Number(values[`endPeriod-${i}`]),teacher:values[`teacher-${i}`],location:values[`location-${i}`],weeks:parseWeeks(values[`weeks-${i}`],semester().totalWeeks),breakMode:values[`breakMode-${i}`]}));}
function detail(id){const o=occurrenceMap.get(id);if(!o)return;if(o.kind==='exam'){exams.detail(o.examId);return;}const c=semester().courses.find(c=>c.id===o.courseId);const conflicts=occurrencesOn(semester(),o.date).filter(x=>x.id!==o.id&&x.startMs<o.endMs&&x.endMs>o.startMs);const timeline=(o.breakMode==='continuous'?[{...o.segments[0],end:o.segments.at(-1).end,endMs:o.endMs}]:o.segments).map((p,i)=>`${i&&p.startMs>o.segments[i-1].endMs?`<div class="timeline-break">${o.segments[i-1].end}–${p.start} · 休息 ${Math.round((p.startMs-o.segments[i-1].endMs)/60000)} 分钟</div>`:''}<div class="timeline-segment"><strong>${p.start}–${p.end}</strong><span>${o.breakMode==='continuous'?`第 ${o.startPeriod}–${o.endPeriod} 节（连上）`:`第 ${p.period} 小节`}</span></div>`).join('');sheet('这一次课程',`<div class="detail-color c${o.color}"></div><h3 class="detail-name">${esc(o.name)}</h3><div class="detail-tags">${o.assessment!=='未设置'?`<span class="pill">${esc(o.assessment)}</span>`:''}${o.nature?`<span class="pill">${esc(o.nature)}</span>`:''}</div><div class="detail-row">${icon('calendar')}<span>${o.date} · 周${DAYS[o.day-1]}<br>第 ${o.startPeriod}–${o.endPeriod} 节${o.changeLabel?` · ${esc(o.changeLabel)}`:''}</span></div><div class="detail-row">${icon('pin')}<span>${esc(o.location||'地点待定')}</span></div><div class="detail-row">${icon('person')}<span>${esc(o.teacher||'教师待定')}</span></div><div class="lesson-timeline">${timeline}</div>${o.note?`<p class="helper-box">${esc(o.note)}</p>`:''}${conflicts.length?`<div class="helper-box warning-box">与 ${conflicts.map(x=>esc(x.name)).join('、')} 时间重叠，请核对。</div>`:''}<div class="sheet-actions">${button('exception','调整本次','secondary',`data-id="${esc(o.id)}"`)}${button('edit','编辑整门课程','primary',`data-id="${esc(c.id)}"`)}</div><div class="sheet-actions">${button('session-edit','编辑这条重复安排','secondary',`data-course="${esc(c.id)}" data-session="${esc(o.sessionId)}"`)}${button('course-delete','删除整门课程','danger',`data-id="${esc(c.id)}"`)}</div>`);}
function allCourses(query=''){sheet('全部课程',`<p class="sheet-subtitle">每门课程可以有多条上课安排。</p><input id="course-search" type="search" placeholder="搜索课程、教师、教室" value="${esc(query)}"><div id="course-results">${courseList(query)}</div>${button('add',`${icon('plus',16)} 添加课程`,'primary full-width','style="margin-top:18px"')}`);}
function courseList(query){return semester().courses.filter(c=>[c.name,c.shortName,...c.sessions.flatMap(s=>[s.teacher,s.location])].join(' ').toLowerCase().includes(query.toLowerCase())).map(c=>`<button class="course-list-item" data-action="edit" data-id="${esc(c.id)}"><i class="course-dot c${c.color}"></i><div><strong>${esc(c.name)}</strong><small>${c.sessions.map(sessionText).join(' / ')}${c.assessment!=='未设置'?` · ${esc(c.assessment)}`:''}</small></div>${icon('right',15)}</button>`).join('')||'<p class="sheet-subtitle" style="padding:24px 0">没有匹配的课程。</p>';}
function semestersSheet(){sheet('我的学期',`<p class="sheet-subtitle">切换学期会同步课表和提醒，其他学期的数据继续保留。</p>${state.semesters.map(s=>`<div class="semester-card"><button data-action="switch-semester" data-id="${esc(s.id)}"><strong>${esc(s.name)}</strong><small>${s.startDate} 起 · ${s.totalWeeks} 周 · ${s.courses.length} 门课</small></button>${s.id===state.activeSemesterId?'<span class="pill">当前</span>':icon('right',16)}</div>`).join('')}<div class="sheet-actions">${button('new-semester','新建学期','primary')}${button('semester-edit','编辑当前学期')}</div>${state.semesters.length>1?button('semester-delete','删除当前学期','text-button','style="color:#a45b43;margin-top:15px"'):''}`);}
function semesterForm(isNew=false){const s=isNew?makeSemester():semester();sheet(isNew?'新建学期':'学期设置',`<form id="semester-form" data-new="${isNew}">${field('学期名称',input('name',s.name,'text','required maxlength="80"'))}${field('第 1 周的周一',input('startDate',s.startDate,'date','required'),'请按学校校历填写，决定单双周与提醒日期。')}${field('学期总周数',input('totalWeeks',s.totalWeeks,'number','min="1" max="30" required'))}${submit()}</form>`);}
function profilesSheet(){const s=semester();sheet('按日期切换作息',`<p class="sheet-subtitle">当天使用最近已生效的方案。可以只设一套，也可按学校通知添加夏季、冬季作息。</p>${[...s.profiles].sort((a,b)=>a.effectiveFrom.localeCompare(b.effectiveFrom)).map(p=>`<button class="profile-card" data-action="profile-edit" data-id="${esc(p.id)}"><div><strong>${esc(p.name)}</strong><small>${p.effectiveFrom} 起生效 · ${p.periods.length} 节</small></div>${icon('right',16)}</button>`).join('')}${button('profile-add',`${icon('plus',16)} 添加生效方案`,'primary full-width','style="margin-top:18px"')}`);}
function profileForm(id){const p=semester().profiles.find(p=>p.id===id),draft=p||{id:uid(),name:'新作息',effectiveFrom:localDate(),periods:clone(getProfile(semester(),localDate()).periods)};sheet(p?'编辑作息方案':'添加作息方案',`<form id="profile-form" data-id="${esc(draft.id)}">${field('方案名称',input('name',draft.name,'text','required maxlength="50" placeholder="例如 夏季作息"'))}${field('生效日期',input('effectiveFrom',draft.effectiveFrom,'date','required'),'从这一天起使用；更早的日期继续使用原方案。')}<div id="period-rows">${draft.periods.map(periodRow).join('')}</div><div class="sheet-actions">${button('period-add','增加一节')}${button('period-remove','减少最后一节')}</div><div class="helper-box">每小节的起止时间独立填写，间隔自动作为休息时间。最多 24 节。</div>${submit()}${p&&semester().profiles.length>1?button('profile-delete','删除此作息方案','text-button',`data-id="${esc(p.id)}" style="color:#a45b43"`):''}</form>`);}
function periodRow(p,i){return `<div class="period-edit"><label>${String(i+1).padStart(2,'0')}</label><input type="time" name="start-${i}" value="${p.start}" required aria-label="第 ${i+1} 节开始"><span>–</span><input type="time" name="end-${i}" value="${p.end}" required aria-label="第 ${i+1} 节结束"></div>`;}

function calendarSheet(){const s=semester();const changes=[...s.dayRules.map(r=>({id:r.id,kind:'rule',date:r.date,title:r.type==='off'?'整日停课':`补 ${r.sourceDate} 的课`,note:r.label})),...s.exceptions.map(e=>({id:e.id,kind:'exception',date:e.date||e.sourceDate,title:`${s.courses.find(c=>c.sessions.some(t=>t.id===e.sessionId))?.name||'课程'} · ${{cancel:'取消本次',move:'移动本次',modify:'调整本次'}[e.type]}`,note:e.note||`原日期 ${e.sourceDate}`})),...s.holidayLabels.map(h=>({id:h.id,kind:'holiday',date:h.date,title:h.name,note:'自定义日期标记'}))].sort((a,b)=>a.date.localeCompare(b.date));sheet('日历与教学调整',`<p class="sheet-subtitle">节假日只标记，不自动停课。整日调整和单次调课会同步到课表与通知。</p><form id="day-jump" class="day-jump">${input('date',localDate(),'date','required')}<button class="secondary" type="submit">查看当天</button></form><div class="sheet-actions">${button('day-rule','停课 / 补课','primary')}${button('holiday','添加日期标记')}</div><div class="section-label">已设置的变更</div>${changes.length?changes.map(c=>`<div class="change-row"><div><small>${c.date}</small><strong>${esc(c.title)}</strong><p>${esc(c.note||'')}</p></div>${button('remove-change','撤销','text-button',`data-id="${esc(c.id)}" data-kind="${c.kind}"`)}</div>`).join(''):'<p class="sheet-subtitle">还没有教学调整。</p>'}<p class="source-note">内置 2026 年中国大陆节假日日期标记，参考国务院办公厅通知；其他年份可手动添加。校内教学以学校通知为准。</p>`);}
function dayDetail(date){const items=occurrencesOn(semester(),date);items.forEach(o=>occurrenceMap.set(o.id,o));const rule=semester().dayRules.find(r=>r.date===date);sheet(`${date} · 周${DAYS[dayNumber(date)-1]}`,`<p class="sheet-subtitle">${esc(holiday(date)||'普通日期')} · ${esc(getProfile(semester(),date).name)}${rule?` · ${rule.type==='off'?'整日停课':'整日补课'}`:''}</p>${items.map(o=>`<button class="preview-course" data-action="detail" data-id="${esc(o.id)}"><div><strong>${esc(o.name)}</strong><p>${o.segments[0].start}–${o.segments.at(-1).end} · ${esc(o.location||'地点待定')}${o.changeLabel?` · ${esc(o.changeLabel)}`:''}</p></div>${icon('right',15)}</button>`).join('')||'<p class="helper-box">这一天没有课程安排。</p>'}<div class="sheet-actions">${button('day-rule','设置整日调整','secondary',`data-date="${date}"`)}${button('holiday','标记日期','secondary',`data-date="${date}"`)}</div><p class="source-note" style="margin-top:15px">点击上方具体课程，可仅调整或取消这一次。</p>`);}
function dayRuleForm(date=localDate()){sheet('整日教学调整',`<form id="day-rule-form">${field('调整日期',input('date',date,'date','required'))}${field('如何安排',select('type',[['off','当天全部停课'],['replace','当天补另一个日期的课']],'off'))}<div id="source-date-field" hidden>${field('补哪一个日期的课',input('sourceDate',date,'date'),'沿用被补日期的周次、单双周，原日期课程会移到调整日期。目标当天原有课程由被补课程替代。')}</div>${field('说明',input('label','','text','maxlength="100" placeholder="例如 校庆停课、学校调休通知"'))}<div class="helper-box">确认前会展示当天安排的变化。若已有调整，请先撤销原规则再设置。</div>${submit('预览调整')}</form>`);}
function holidayForm(date=localDate()){sheet('添加日期标记',`<form id="holiday-form">${field('日期',input('date',date,'date','required'))}${field('名称',input('name','','text','required maxlength="40" placeholder="例如 运动会、校庆、考试周"'))}<p class="sheet-subtitle">标记不会改变课程。如需停课，请另设整日调整。</p>${submit()}</form>`);}
function exceptionForm(id){const o=occurrenceMap.get(id);if(!o)return;sheet('只调整这一次',`<form id="exception-form" data-occurrence="${esc(id)}"><p class="sheet-subtitle">${esc(o.name)} · ${o.date}，其他周次保持原安排。</p>${field('调整方式',select('action',[['adjust','移动 / 修改时间地点'],['cancel','取消这一次']],'adjust'))}<div id="exception-fields">${field('实际上课日期',input('date',o.date,'date','required'))}<div class="form-row">${field('开始节次',select('startPeriod',periodOptions(),o.startPeriod))}${field('结束节次',select('endPeriod',periodOptions(),o.endPeriod))}</div>${field('教室',input('location',o.location,'text','maxlength="150"'))}${field('教师',input('teacher',o.teacher,'text','maxlength="100"'))}</div>${field('说明',input('note','','text','maxlength="2000" placeholder="调课原因（选填）"'))}${submit('预览本次调整')}</form>`);}
let pendingChange=null;
function confirmChange(next,label,message){const checked=validateState(next);pendingChange={next:checked,label};sheet('确认这次变更',`<div class="helper-box">${message}</div><p class="sheet-subtitle">保存前会保留恢复版本。课程提醒会同步更新。</p><div class="sheet-actions">${button('close','暂不修改')}${button('apply-change','确认保存','primary')}</div>`);}
function reviewSemester(next,label,message,dates=[]){const conflictDates=[];if(!dates.length)dates=notificationEvents(next).filter(o=>o.conflict||o.onOffDay).map(o=>o.date);for(const d of [...new Set(dates)]){const occurrences=occurrencesOn(next,d);if(occurrences.some(o=>o.conflict||o.onOffDay))conflictDates.push(d);}confirmChange({...state,semesters:state.semesters.map(s=>s.id===next.id?next:s)},label,`${message}${conflictDates.length?`<br><strong>请注意：${conflictDates.join('、')} 有时间重叠或停课日安排。</strong>`:''}`);}

function importSheet(){if(!state.semesters.some(s=>s.id===importTargetId))importTargetId=state.activeSemesterId;sheet('导入课程',`${field('导入到哪个学期',select('importTarget',state.semesters.map(s=>[s.id,s.name]),importTargetId))}${button('import-new-semester','＋ 新建学期','text-button')}<p class="sheet-subtitle">识别后先核对，已有课程不会直接覆盖。</p><div class="import-method"><span class="method-icon">${icon('school',24)}</span><div><h3>正方教务</h3><p>填写学校网址，在学校网页自行登录。</p></div></div><form id="school-form">${field('教务系统网址',input('url',state.preferences.schoolUrl,'url','required placeholder="https://你的学校教务地址"'),'会记住此网址。可从官网逐步进入课表，再点“导入此页”。账号密码在学校网页输入。')}<button type="submit" class="primary full-width">打开教务系统 ${icon('arrow',16)}</button>${errorBox}</form><div class="divider">或从本地导入</div>${button('pdf-import',`${icon('file',18)} 选择课表 PDF`,'secondary full-width')}<p class="source-note" style="margin:10px 0 16px">支持含文字的正方课表 PDF，最多 20MB、30 页；本地识别。扫描件暂不支持。</p>${button('paste-import',`${icon('note',17)} 粘贴文字 / HTML / JSON`,'secondary full-width')}<div class="helper-box">重新导入会标出新增、变化和缺失条目。手动修改会保留，停课和调课记录不会被覆盖。</div>`);}
function pasteSheet(){sheet('粘贴课表',`<form id="paste-form"><p class="sheet-subtitle">每条安排需包含课程名、星期、节次和周次。</p>${field('课表内容','<textarea name="content" rows="9" required placeholder="高等数学&#10;周一 第1-2节 第1-16周&#10;教师：王老师&#10;教室：理2305"></textarea>')}${submit('识别并核对')}</form>`);}
async function previewImport(result,kind='text'){
  const {diffImport}=await import('./import-diff.js');
  importPreview={result,kind,diff:diffImport(importSemester(),result.courses,{kind,source:result.source||kind}),semesterId:importSemester().id};
  showImportDiff();
}
function showImportDiff(){
  const {result,diff}=importPreview;const labels={new:'新增',same:'相同',changed:'有变化',missing:'来源缺失',ambiguous:'需要核对'};
  sheet('核对导入差异',`<p class="sheet-subtitle">导入到「${esc(state.semesters.find(s=>s.id===importPreview.semesterId)?.name||'所选学期')}」。识别 ${result.courses.length} 条安排，默认仅选新增项。</p>${[...result.warnings,...diff.warnings].length?`<div class="helper-box warning-box">${[...result.warnings,...diff.warnings].map(esc).join('<br>')}</div>`:''}<div class="diff-counts">${Object.entries(labels).map(([k,v])=>`<span>${v} ${diff.items.filter(x=>x.status===k).length}</span>`).join('')}</div><div class="preview-list">${diff.items.map(item=>{const c=item.incoming||item.before||{};const actionable=['new','changed','ambiguous'].includes(item.status);return `<div class="diff-item"><label><input name="import-item" type="checkbox" value="${esc(item.key)}" ${item.status==='new'?'checked':''} ${!actionable?'disabled':''}><span><strong>${esc(c.name||item.after?.name||'现有安排')}</strong><small>${c.day?sessionText(c):''}${c.weeks?` · ${weeksText(c.weeks)}`:''}</small><small>${esc(c.location||'')} ${esc(c.teacher||'')}</small></span><em class="diff-${item.status}">${labels[item.status]}</em></label><p>${esc(item.message||'')}</p>${importChanges(item)}${item.protectedFields?.length?`<p class="protected-note">保留字段：${item.protectedFields.map(f=>esc(importFieldNames[f]||f)).join('、')}</p>`:''}${item.status==='ambiguous'?'<p class="protected-note">勾选后将新增为独立课程，不合并现有课程。</p>':''}${item.incoming?button('import-edit','修正识别结果','text-button',`data-key="${esc(item.key)}"`):''}</div>`;}).join('')}</div>${!result.courses.length?'<div class="helper-box">没有完整课程可以导入，请检查文件或页面；可用手动添加补齐。</div>':''}<p class="source-note" style="margin-top:12px">来源：${esc(result.source)}<br>缺失项不会自动删除。开学日期与作息请在设置核对。</p><div class="sheet-actions">${button('import','返回')}${button('confirm-import','确认所选变更','primary',!diff.items.some(i=>['new','changed','ambiguous'].includes(i.status))?'disabled':'')}</div>`);
}
const importFieldNames={name:'名称',day:'星期',startPeriod:'开始节次',endPeriod:'结束节次',weeks:'周次',teacher:'教师',location:'教室'};
function importChanges(item){if(item.status!=='changed'||!item.before||!item.after)return '';const show=(key,value)=>key==='weeks'?weeksText(value):key==='day'?`周${DAYS[value-1]}`:['startPeriod','endPeriod'].includes(key)?`第 ${value} 节`:String(value||'未填写');return `<div class="import-changes">${Object.entries(importFieldNames).filter(([key])=>JSON.stringify(item.before[key])!==JSON.stringify(item.incoming[key])).map(([key,label])=>`<p><b>${label}</b>：${esc(show(key,item.before[key]))} → ${esc(show(key,item.incoming[key]))}${JSON.stringify(item.after[key])!==JSON.stringify(item.incoming[key])?`<br><span class="protected-note">实际保留：${esc(show(key,item.after[key]))}</span>`:''}</p>`).join('')}</div>`;}
function importEdit(key){const item=importPreview.diff.items.find(i=>i.key===key);if(!item?.incoming)return;const c=item.incoming;sheet('修正这条识别结果',`<form id="import-edit-form" data-key="${esc(key)}">${field('名称',input('name',c.name,'text','required maxlength="100"'))}<div class="form-row three">${field('星期',select('day',DAYS.map((d,i)=>[i+1,`周${d}`]),c.day))}${field('开始',select('startPeriod',periodOptions(importSemester()),c.startPeriod))}${field('结束',select('endPeriod',periodOptions(importSemester()),c.endPeriod))}</div>${field('周次',input('weeks',c.weeks.join(','),'text','required'))}${field('地点',input('location',c.location))}${field('教师',input('teacher',c.teacher))}${field('考核方式',input('assessment',c.assessment||'未设置','text','maxlength="30"'))}${submit('重新核对差异')}</form>`);}
async function importPdfBytes(bytes,name){if(pdfBusy){toast('正在识别上一份 PDF');return;}pdfBusy=true;sheet('正在读取 PDF',`<div class="pdf-loading">${icon('file',38)}<h3>${esc(name||'课表.pdf')}</h3><p>正在本地还原文字与表格，请稍候…</p></div>`);try{const {parsePdf}=await import('./pdf-import.js');const result=await parsePdf(bytes,{totalWeeks:importSemester().totalWeeks,name});await previewImport(result,'pdf');}catch(e){sheet('PDF 暂未识别成功',`<div class="helper-box warning-box">${esc(e.message)}</div>${button('import','返回导入','primary full-width')}`);}finally{pdfBusy=false;}}
function choosePdf(){if(window.Android?.importPdf){Android.importPdf();return;}const picker=document.createElement('input');picker.type='file';picker.accept='.pdf,application/pdf';picker.onchange=async()=>{const f=picker.files[0];if(!f)return;if(f.size>20*1024*1024){toast('请选择 20MB 以内的 PDF');return;}await importPdfBytes(new Uint8Array(await f.arrayBuffer()),f.name);};picker.click();}
window.onPdfLoaded=async payload=>{try{const bin=atob(payload.base64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);await importPdfBytes(bytes,payload.name);}catch(e){toast(`PDF 读取失败：${e.message}`);}};
window.onPdfError=p=>toast(p.message||'PDF 读取失败');
window.onSchoolCapture=async payload=>{try{await previewImport(parseSchedule(typeof payload==='string'?JSON.parse(payload):payload,importSemester().totalWeeks),'web');}catch(e){toast(`导入失败：${e.message}`);}};

function notificationSheet(){
  if(window.Android?.getNotificationStatus)try{notificationStatus=JSON.parse(Android.getNotificationStatus());}catch{}
  const n=state.preferences.notifications,st=notificationStatus;
  sheet('提醒与课程状态',`<form id="notification-form"><label class="check-row"><input type="checkbox" name="enabled" ${n.enabled?'checked':''}><span><strong>课前提醒</strong><small>课程名、地点与开始时间</small></span></label>${field('提前多少分钟',input('minutes',n.minutes,'number','min="0" max="120" required'))}<label class="check-row"><input type="checkbox" name="ongoing" ${n.ongoing?'checked':''}><span><strong>课程状态通知</strong><small>上课 / 课间自动切换，当天结束后收起</small></span></label>${field('上课时的计时方式',select('statusMode',[['remaining','距离课间 / 下课'],['elapsed','累计授课时间（不含课间）']],n.statusMode||'remaining'))}<label class="check-row"><input type="checkbox" name="breakReminder" ${n.breakReminder?'checked':''}><span><strong>课间结束提醒</strong><small>同一堂课第二小节开始时，再提醒一次</small></span></label>${submit('保存提醒设置')}</form><div id="notification-permissions" class="helper-box ${st.granted&&st.exact?'':'warning-box'}">${window.Android?`通知权限：${st.granted?'已允许':'尚未允许'}<br>准时提醒：${st.exact?'已允许':'未授权，将使用可能延迟的系统调度'}${st.remindersAllowed===false?'<br>课前提醒频道未开启':''}${st.statusAllowed===false?'<br>课程状态频道未开启':''}`:'浏览器预览不发送系统通知，请在 Android App 中使用。'}</div>${window.Android?`<div class="permission-actions">${button('permission-notification','通知权限')}${button('permission-alarm','准时提醒权限')}${button('test-notification','发送测试通知')}</div>`:''}<p class="source-note">提醒跟随当前学期、调课及作息更新。Android 14 允许划掉状态通知；系统强行停止应用后，请重新打开以恢复计划。</p>`);
}
function refreshPermissionRegion(){const el=document.querySelector('#notification-permissions');if(!el)return;const st=notificationStatus;el.classList.toggle('warning-box',!st.granted||!st.exact);el.innerHTML=window.Android?`通知权限：${st.granted?'已允许':'尚未允许'}<br>准时提醒：${st.exact?'已允许':'未授权，将使用可能延迟的系统调度'}${st.remindersAllowed===false?'<br>课前提醒频道未开启':''}${st.statusAllowed===false?'<br>课程状态频道未开启':''}`:'浏览器预览不发送系统通知，请在 Android App 中使用。';}
function refreshNotificationStatus(){if(window.Android?.getNotificationStatus)try{notificationStatus=JSON.parse(Android.getNotificationStatus());refreshPermissionRegion();}catch{}}
window.onNotificationStatus=s=>{notificationStatus=typeof s==='string'?JSON.parse(s):s;refreshPermissionRegion();};
window.onScheduleSyncError=e=>toast(`提醒未保存：${e.message}`);
function exportBackup(raw){const text=raw||(storageError?(localStorage.getItem(STATE_KEY)||localStorage.getItem('qingke.data.v1')):JSON.stringify(state,null,2));if(!text){toast('没有可导出的数据');return;}if(window.Android?.exportBackup){Android.exportBackup(text);return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`清课备份-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('备份已生成');}
function chooseBackup(){if(window.Android?.importBackup){Android.importBackup();return;}const picker=document.createElement('input');picker.type='file';picker.accept='.json,application/json';picker.onchange=async()=>{const f=picker.files[0];if(!f)return;if(f.size>5*1024*1024){toast('请选择 5MB 以内的备份');return;}window.onBackupLoaded(await f.text());};picker.click();}
window.onBackupLoaded=raw=>{try{restoreDraft=migrateState(typeof raw==='string'?JSON.parse(raw):raw);sheet('恢复这份备份？',`<div class="helper-box">${restoreDraft.semesters.length} 个学期，${restoreDraft.semesters.reduce((n,s)=>n+s.courses.length,0)} 门课程。</div><p class="sheet-subtitle">恢复将替换当前全部学期。保存前会自动保留当前版本。</p><div class="sheet-actions">${button('export','先导出当前')}${button('confirm-restore','确认恢复','primary')}</div>`);}catch(e){toast(`备份无效：${e.message}`);}};
window.onBackupSaved=success=>{if(success)toast('备份已保存');};
window.onNativeMessage=toast;
function recoverySheet(){let list;try{list=recoveries();}catch{toast('恢复记录无法读取，请先导出当前备份');return;}sheet('恢复历史版本',`<p class="sheet-subtitle">保留重要升级版本和最近 4 次重要变更。文件仍在本机，卸载前请导出备份。</p>${list.map(r=>`<div class="change-row"><div><strong>${esc(r.label)}</strong><small>${new Date(r.at).toLocaleString('zh-CN')}</small></div>${button('recovery-restore','恢复','text-button',`data-id="${esc(r.id)}"`)}${button('recovery-export','导出','text-button',`data-id="${esc(r.id)}"`)}</div>`).join('')||'<p class="helper-box">暂时没有历史版本。</p>'}`);}

function singleSessionEditor(courseId,sessionId){const c=semester().courses.find(c=>c.id===courseId),s=c?.sessions.find(s=>s.id===sessionId);if(!s)return;courseDraft={...clone(c),sessions:[clone(s)]};sheet('编辑这条重复安排',`<form id="single-session-form" data-course="${esc(courseId)}" data-session="${esc(sessionId)}"><p class="sheet-subtitle">${esc(c.name)}。只影响这条星期、节次和周次安排，其余上课时间不变。</p>${sessionEditor(s,0)}${submit('保存此安排')}</form>${button('session-delete','删除这条重复安排','danger full-width',`data-course="${esc(courseId)}" data-session="${esc(sessionId)}" style="margin-top:12px"`)}`);}
function deleteCourse(id){const s=clone(semester()),c=s.courses.find(c=>c.id===id);if(!c)return;s.courses=s.courses.filter(c=>c.id!==id);const ids=new Set(c.sessions.map(x=>x.id));s.exceptions=s.exceptions.filter(e=>!ids.has(e.sessionId));reviewSemester(s,'删除整门课程前',`删除「${esc(c.name)}」及其 ${c.sessions.length} 条重复安排和关联单次变更。`);}
function periodAdd(){const root=document.querySelector('#period-rows'),rows=root.querySelectorAll('.period-edit');if(rows.length>=24){toast('最多支持 24 节');return;}const end=rows[rows.length-1].querySelector('input:last-child').value||'08:00';const n=Number(end.slice(0,2))*60+Number(end.slice(3))+10;const t=x=>`${String(Math.floor(Math.min(x,1439)/60)).padStart(2,'0')}:${String(Math.min(x,1439)%60).padStart(2,'0')}`;root.insertAdjacentHTML('beforeend',periodRow({start:t(n),end:t(n+45)},rows.length));}

function refreshContext(){week=clampWeek(currentWeek());threeStart=localDate();importTargetId=state.activeSemesterId;closeSheet();render();if(returnToImport){returnToImport=false;importSheet();}}
function navigatePage(delta){if(state.preferences.viewMode==='three')threeStart=addDays(threeStart,delta*3);else{const next=clampWeek(week+delta);if(next===week)return false;week=next;}render();motion?.animatePage(delta);return true;}
const managerContext={getState:()=>state,getSemester:semester,save,reviewSemester,confirmChange,refresh:refreshContext};
management=createManagementUI(managerContext);exams=createExamUI(managerContext);sharing=createShareUI({...managerContext,canSync:()=>!document.hidden&&!document.querySelector('#modal-root').firstChild,onSynced:()=>render()});
updater=createUpdateUI();
motion=installTimetableMotion({root:app,onNavigate:navigatePage});
document.addEventListener('click',async event=>{
  if(motion?.suppressClick()){event.preventDefault();return;}
  if(event.target.hasAttribute('data-backdrop')){goBack();return;}
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  const {action,id}=el.dataset;
  try{if(await updater.click(action,el)||management.click(action,el)||exams.click(action,el)||await sharing.click(action,el))return;switch(action){
    case 'close':returnToImport=false;closeSheet();break;
    case 'sheet-back':goBack();break;
    case 'tab':if(tab!==el.dataset.tab){tabHistory.push({tab,scroll:window.scrollY});if(tabHistory.length>20)tabHistory.shift();tab=el.dataset.tab;render();window.scrollTo(0,0);motion.animateTab();}break;
    case 'backup-menu':sheet('备份与恢复',`<p class="sheet-subtitle">文件备份可用于换机；历史版本用于撤销近期修改。</p>${settingRow('export','download','导出全部学期','保存为手机外也可留存的 JSON 文件')}${settingRow('restore','upload','从文件恢复','校验并确认后恢复全部学期')}${settingRow('recovery','undo','恢复历史版本','查看升级和重要修改前的记录')}`);break;
    case 'axis-help':sheet('各日作息',visibleDates().map(d=>{const p=getProfile(semester(),d);return `<div class="helper-box"><strong>${d} · ${esc(p.name)}</strong><p>${p.periods.map((t,i)=>`${i+1}节 ${t.start}–${t.end}`).join('<br>')}</p></div>`;}).join(''));break;
    case 'view':if(save({...state,preferences:{...state.preferences,viewMode:el.dataset.view}})){threeStart=week===clampWeek(currentWeek())?localDate():getWeekDates(semester().startDate,week)[0];render();}break;
    case 'prev':case 'next':navigatePage(action==='prev'?-1:1);break;
    case 'today-date':week=clampWeek(currentWeek());threeStart=localDate();render();break;
    case 'choose-week':chooseWeek();break;
    case 'set-week':week=Number(el.dataset.week);threeStart=getWeekDates(semester().startDate,week)[0];closeSheet();render();break;
    case 'add-menu':sheet('添加安排',`<div class="sheet-actions">${button('add',`${icon('grid',19)} 添加课程`,'primary')}${button('exam-add',`${icon('note',19)} 添加考试`)}</div>`);break;
    case 'add':editCourse();break;
    case 'import-new-semester':returnToImport=true;management.click('new-semester',el);break;
    case 'edit':editCourse(id);break;
    case 'detail':detail(id);break;
    case 'all-courses':allCourses();break;
    case 'color':document.querySelectorAll('.color-dot').forEach(x=>x.classList.toggle('selected',x===el));break;
    case 'add-session':readCourseDraft();courseDraft.sessions.push(newSession());showCourseEditor();break;
    case 'remove-session':readCourseDraft();courseDraft.sessions.splice(Number(el.dataset.index),1);showCourseEditor();break;
    case 'session-weeks':{const value=el.dataset.value;document.querySelector(`[name="weeks-${el.dataset.index}"]`).value=Array.from({length:semester().totalWeeks},(_,i)=>i+1).filter(n=>value==='all'||value==='odd'&&n%2===1||value==='even'&&n%2===0).join(',');break;}
    case 'session-edit':singleSessionEditor(el.dataset.course,el.dataset.session);break;
    case 'course-delete':deleteCourse(id);break;
    case 'session-delete':{const s=clone(semester()),c=s.courses.find(c=>c.id===el.dataset.course);if(c.sessions.length===1){deleteCourse(c.id);break;}c.sessions=c.sessions.filter(t=>t.id!==el.dataset.session);s.exceptions=s.exceptions.filter(e=>e.sessionId!==el.dataset.session);reviewSemester(s,'删除重复安排前',`删除「${esc(c.name)}」的这条重复安排与关联单次变更，其他安排保留。`);break;}
    case 'semesters':semestersSheet();break;
    case 'new-semester':semesterForm(true);break;
    case 'semester-edit':semesterForm(false);break;
    case 'switch-semester':if(save({...state,activeSemesterId:id})){week=clampWeek(currentWeek());threeStart=localDate();closeSheet();render();}break;
    case 'semester-delete':{if(state.semesters.length<2)break;const remaining=state.semesters.filter(s=>s.id!==semester().id);confirmChange({...state,semesters:remaining,activeSemesterId:remaining[0].id},'删除学期前',`删除「${esc(semester().name)}」及其课程、作息和调课记录。`);break;}
    case 'profiles':profilesSheet();break;
    case 'profile-add':profileForm();break;
    case 'profile-edit':profileForm(id);break;
    case 'profile-delete':{const s=clone(semester()),p=s.profiles.find(p=>p.id===id);s.profiles=s.profiles.filter(p=>p.id!==id);reviewSemester(s,'删除作息方案前',`删除「${esc(p.name)}」后，对应日期将改用之前生效的方案。`);break;}
    case 'period-add':periodAdd();break;
    case 'period-remove':{const rows=document.querySelectorAll('#period-rows .period-edit');if(rows.length>1)rows[rows.length-1].remove();break;}
    case 'toggle-weekend':if(updateSemester({...semester(),showWeekend:!semester().showWeekend}))render();break;
    case 'calendar':calendarSheet();break;
    case 'day-detail':dayDetail(el.dataset.date);break;
    case 'day-rule':dayRuleForm(el.dataset.date);break;
    case 'holiday':holidayForm(el.dataset.date);break;
    case 'exception':exceptionForm(id);break;
    case 'remove-change':{const s=clone(semester()),key={rule:'dayRules',exception:'exceptions',holiday:'holidayLabels'}[el.dataset.kind];s[key]=s[key].filter(x=>x.id!==id);reviewSemester(s,'撤销教学调整前','撤销这条变更，相关课程会重新按其余有效规则显示。');break;}
    case 'apply-change':{const oldSemester=state.activeSemesterId;if(pendingChange&&save(pendingChange.next,pendingChange.label)){pendingChange=null;if(oldSemester!==state.activeSemesterId||returnToImport)refreshContext();else{week=clampWeek(week);closeSheet();render();}toast('变更已保存，可从历史版本恢复');}break;}
    case 'import':importSheet();break;
    case 'paste-import':pasteSheet();break;
    case 'pdf-import':choosePdf();break;
    case 'import-edit':importEdit(el.dataset.key);break;
    case 'confirm-import':{
      const target=state.semesters.find(s=>s.id===importPreview.semesterId);if(!target)throw Error('所选学期已删除，请重新选择');
      const selected=[...document.querySelectorAll('[name="import-item"]:checked')].map(x=>{const item=importPreview.diff.items.find(i=>i.key===x.value);return item.status==='ambiguous'?{key:x.value,action:'add'}:x.value;});
      if(!selected.length){toast('请先勾选要导入的新增或变更项');break;}
      const {applyImport}=await import('./import-diff.js');const next=applyImport(target,importPreview.diff,selected);
      if(save({...state,semesters:state.semesters.map(s=>s.id===next.id?next:s),activeSemesterId:next.id},'重新导入前')){refreshContext();toast('所选课程已导入目标学期，手动调课记录已保留');}break;
    }
    case 'notifications':notificationSheet();break;
    case 'permission-notification':if(window.Android){notificationStatus.granted?Android.openNotificationSettings():Android.requestNotifications();}break;
    case 'permission-alarm':window.Android?.openExactAlarmSettings?.();break;
    case 'test-notification':window.Android?.testNotification?.();break;
    case 'export':exportBackup();break;
    case 'restore':chooseBackup();break;
    case 'recovery':recoverySheet();break;
    case 'recovery-export':{const r=recoveries().find(r=>r.id===id);if(r)exportBackup(r.raw);break;}
    case 'recovery-restore':{const r=recoveries().find(r=>r.id===id);if(r)window.onBackupLoaded(r.raw);break;}
    case 'confirm-restore':{if(!restoreDraft)break;const oldError=storageError;storageError='';if(save(restoreDraft,'恢复备份前')){week=clampWeek(currentWeek());threeStart=localDate();closeSheet();render();toast('全部学期已恢复');}else storageError=oldError;break;}
  }}catch(e){toast(e.message);console.error(e);}
});
document.addEventListener('input',event=>{if(event.target.id==='course-search')document.querySelector('#course-results').innerHTML=courseList(event.target.value.trim());});
document.addEventListener('change',event=>{
  try{if(event.target.name==='importTarget'){importTargetId=event.target.value;return;}if(management.change(event.target)||exams.change(event.target)||sharing.change?.(event.target))return;}catch(e){toast(e.message);return;}
  if(event.target.closest('#day-rule-form')&&event.target.name==='type')document.querySelector('#source-date-field').hidden=event.target.value!=='replace';
  if(event.target.closest('#exception-form')&&event.target.name==='action')document.querySelector('#exception-fields').hidden=event.target.value==='cancel';
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target,values=Object.fromEntries(new FormData(form)),error=form.querySelector('#form-error');if(error)error.textContent='';
  try{if(await updater.submit(form,values)||management.submit(form,values)||exams.submit(form,values)||await sharing.submit(form,values))return;switch(form.id){
    case 'course-form':{
      readCourseDraft();const s=clone(semester()),old=s.courses.find(c=>c.id===courseDraft.id),newIds=new Set(courseDraft.sessions.map(x=>x.id));
      if(old){const removed=new Set(old.sessions.filter(x=>!newIds.has(x.id)).map(x=>x.id));s.exceptions=s.exceptions.filter(e=>!removed.has(e.sessionId));}
      s.courses=[...s.courses.filter(c=>c.id!==courseDraft.id),courseDraft];
      const checked=validateState({...state,semesters:state.semesters.map(x=>x.id===s.id?s:x)}),events=notificationEvents(checked.semesters.find(x=>x.id===s.id)),conflicts=events.filter(o=>o.courseId===courseDraft.id&&o.conflict);
      if(conflicts.length){confirmChange(checked,'保存课程前',`这门课程在 ${new Set(conflicts.map(o=>o.date)).size} 个日期与其他课程时间重叠。确认仍要保存吗？`);break;}
      if(save(checked,draftEditing?'编辑整门课程前':'')){closeSheet();render();toast('课程及所有上课安排已保存');}break;
    }
    case 'single-session-form':{
      const s=clone(semester()),c=s.courses.find(c=>c.id===form.dataset.course),old=c.sessions.find(t=>t.id===form.dataset.session);
      const session={...old,day:Number(values['day-0']),startPeriod:Number(values['startPeriod-0']),endPeriod:Number(values['endPeriod-0']),weeks:parseWeeks(values['weeks-0'],s.totalWeeks),teacher:values['teacher-0'],location:values['location-0'],breakMode:values['breakMode-0']};
      c.sessions=c.sessions.map(t=>t.id===session.id?session:t);reviewSemester(s,'编辑重复安排前',`更新「${esc(c.name)}」的这一条重复安排。`,notificationEvents(s).filter(o=>o.sessionId===session.id).map(o=>o.date));break;
    }
    case 'semester-form':{
      const isNew=form.dataset.new==='true';
      if(isNew){const next=makeSemester({name:values.name,startDate:values.startDate,totalWeeks:Number(values.totalWeeks)});if(save({...state,semesters:[...state.semesters,next],activeSemesterId:next.id},'新建学期前')){week=clampWeek(currentWeek());closeSheet();render();toast('新学期已创建');}}
      else{const s=clone(semester()),oldStart=s.startDate;s.name=values.name;s.startDate=values.startDate;s.totalWeeks=Number(values.totalWeeks);if(s.profiles.length===1&&s.profiles[0].effectiveFrom===oldStart)s.profiles[0].effectiveFrom=s.startDate;reviewSemester(s,'修改学期设置前','更新开学日期或周数会重新计算课程日期和提醒。已有调课如不再对应原安排，会要求先处理。');}break;
    }
    case 'profile-form':{
      const s=clone(semester()),count=form.querySelectorAll('.period-edit').length,p={id:form.dataset.id,name:values.name,effectiveFrom:values.effectiveFrom,periods:Array.from({length:count},(_,i)=>({start:values[`start-${i}`],end:values[`end-${i}`]}))};s.profiles=[...s.profiles.filter(x=>x.id!==p.id),p];reviewSemester(s,'修改作息前',`从 ${esc(p.effectiveFrom)} 起使用「${esc(p.name)}」，共 ${count} 节。课表与提醒按实际上课日期应用。`);break;
    }
    case 'day-jump':dayDetail(values.date);break;
    case 'day-rule-form':{
      const s=clone(semester()),r={id:uid(),date:values.date,type:values.type,label:values.label,...(values.type==='replace'?{sourceDate:values.sourceDate}:{})};
      const before=occurrencesOn(s,r.date);s.dayRules.push(r);const after=occurrencesOn(s,r.date);
      reviewSemester(s,'设置整日调整前',`${r.date} 原有 ${before.length} 次安排，调整后 ${after.length} 次。${r.type==='replace'?`<br>将 ${r.sourceDate} 的课程移至这一天；使用被补日期的单双周和目标当天的作息。`:'<br>当天基础课程停课；已明确移入的单次调课会保留并提示冲突。'}`,[r.date,r.sourceDate].filter(Boolean));break;
    }
    case 'holiday-form':{
      const s=clone(semester());s.holidayLabels=[...s.holidayLabels.filter(h=>h.date!==values.date),{id:uid(),date:values.date,name:values.name}];if(updateSemester(s,'添加日期标记前')){closeSheet();render();toast('日期标记已保存，不改变课程');}break;
    }
    case 'exception-form':{
      const o=occurrenceMap.get(form.dataset.occurrence);if(!o)throw Error('课程已变化，请重新打开详情');const s=clone(semester());
      const e={id:uid(),sessionId:o.sessionId,sourceDate:o.sourceDate,type:values.action==='cancel'?'cancel':'move',note:values.note};
      if(e.type!=='cancel')Object.assign(e,{date:values.date,startPeriod:Number(values.startPeriod),endPeriod:Number(values.endPeriod),location:values.location,teacher:values.teacher});
      s.exceptions=[...s.exceptions.filter(x=>!(x.sessionId===e.sessionId&&x.sourceDate===e.sourceDate)),e];
      reviewSemester(s,'单次调课前',e.type==='cancel'?`取消「${esc(o.name)}」在 ${o.date} 的这一次安排。`:`「${esc(o.name)}」调整为 ${esc(values.date)} 第 ${e.startPeriod}–${e.endPeriod} 节，${esc(e.location||'地点待定')}。`,[o.date,values.date]);break;
    }
    case 'school-form':{
      const url=new URL(values.url.trim());if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error('请输入不含账号密码的 HTTP / HTTPS 教务网址');
      if(save({...state,preferences:{...state.preferences,schoolUrl:url.href}})){if(window.Android?.openSchool){Android.openSchool(url.href);closeSheet();}else{window.open(url.href,'_blank','noopener,noreferrer');toast('网页预览可粘贴课表；Android 内可直接导入此页');}}break;
    }
    case 'paste-form':{const content=values.content.trim();if(content.length>4*1024*1024)throw Error('内容过长，请只复制课表区域');await previewImport(parseSchedule({text:content,html:content.includes('<')?content:'',title:'粘贴的课表'},importSemester().totalWeeks),'text');break;}
    case 'import-edit-form':{
      const item=importPreview.diff.items.find(i=>i.key===form.dataset.key),source=item.incoming,index=importPreview.result.courses.findIndex(c=>c.id===source.id);
      if(index<0)throw Error('该识别条目已更新，请重新导入');const changed={...source,...values,day:Number(values.day),startPeriod:Number(values.startPeriod),endPeriod:Number(values.endPeriod),weeks:parseWeeks(values.weeks,importSemester().totalWeeks)};
      if(!changed.weeks.length)throw Error('请填写有效周次');importPreview.result.courses[index]=changed;await previewImport(importPreview.result,importPreview.kind);break;
    }
    case 'notification-form':{
      const n={enabled:values.enabled==='on',ongoing:values.ongoing==='on',minutes:Number(values.minutes),breakReminder:values.breakReminder==='on',statusMode:values.statusMode};
      if(save({...state,preferences:{...state.preferences,notifications:n}})){closeSheet();render();toast('提醒设置已保存');if((n.enabled||n.ongoing)&&window.Android?.requestNotifications&&!notificationStatus.granted)Android.requestNotifications();}break;
    }
  }}catch(e){if(error)error.textContent=e.message;else toast(e.message);console.error(e);}
});
function goBack(){if(backSheet()){if(!document.querySelector('#modal-root').firstChild)returnToImport=false;refreshNotificationStatus();return true;}const previous=tabHistory.pop();if(previous){tab=previous.tab;render();window.scrollTo(0,previous.scroll);motion.animateTab();return true;}return false;}
window.onNativeBack=goBack;
document.addEventListener('keydown',event=>{if(event.key==='Escape'){goBack();}if(event.key==='Tab'&&document.querySelector('#modal-root').firstChild){const items=[...document.querySelectorAll('#modal-root button:not(:disabled),#modal-root input:not(:disabled),#modal-root textarea,#modal-root select')].filter(x=>x.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
let previousDate=localDate(),previousWeek=currentWeek();
function refreshClock(){if(document.hidden||document.querySelector('#modal-root').firstChild)return;const date=localDate();if(date!==previousDate){if(week===clampWeek(previousWeek))week=clampWeek(currentWeek());if(threeStart===previousDate)threeStart=date;previousDate=date;previousWeek=currentWeek();syncNative();render();}else if(tab==='today')render();else if(tab==='table')refreshCourseProgress(app,occurrenceMap);}
document.addEventListener('visibilitychange',refreshClock);window.addEventListener('focus',refreshClock);setInterval(refreshClock,30000);
window.addEventListener('focus',()=>{refreshNotificationStatus();sharing.onForeground?.();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshNotificationStatus();sharing.onForeground?.();}});
setInterval(()=>{if(!document.hidden&&!document.querySelector('#modal-root').firstChild)refreshCourseProgress(app,occurrenceMap);},1000);
render();syncNative();sharing.onForeground?.();
